#include <bits/stdc++.h>
using namespace std;

// 2D Segment Tree: flattened storage
// Grid size: R x C, 0-based indices. Supports min over subrectangles.

int R, C, Q;
vector<int> grid; // size R*C

// Flattened 2D segtree storage
// Outer x-dimension size: NX = 4*R, inner y-dimension size: NY = 4*C
size_t NY; // number of elements per x-node's y-tree
size_t NX; // number of x-nodes
vector<int> seg; // size NX * NY

inline int idx(size_t x, size_t y) {
    return int(x * NY + y);
}

void build_y_from_row(size_t x, size_t y, int ly, int ry, int row) {
    if (ly == ry) {
        seg[idx(x, y)] = grid[row * C + ly];
    } else {
        int mid = (ly + ry) >> 1;
        build_y_from_row(x, y << 1, ly, mid, row);
        build_y_from_row(x, y << 1 | 1, mid + 1, ry, row);
        seg[idx(x, y)] = std::min(seg[idx(x, y << 1)], seg[idx(x, y << 1 | 1)]);
    }
}

void build_y_merge(size_t x, size_t y, int ly, int ry, size_t leftX, size_t rightX) {
    if (ly == ry) {
        seg[idx(x, y)] = std::min(seg[idx(leftX, y)], seg[idx(rightX, y)]);
    } else {
        int mid = (ly + ry) >> 1;
        build_y_merge(x, y << 1, ly, mid, leftX, rightX);
        build_y_merge(x, y << 1 | 1, mid + 1, ry, leftX, rightX);
        seg[idx(x, y)] = std::min(seg[idx(x, y << 1)], seg[idx(x, y << 1 | 1)]);
    }
}

void build_x(size_t x, int lx, int rx) {
    if (lx == rx) {
        build_y_from_row(x, 1, 0, C - 1, lx);
    } else {
        int mid = (lx + rx) >> 1;
        build_x(x << 1, lx, mid);
        build_x(x << 1 | 1, mid + 1, rx);
        build_y_merge(x, 1, 0, C - 1, x << 1, x << 1 | 1);
    }
}

int query_y(size_t x, size_t y, int ly, int ry, int qy1, int qy2) {
    if (qy1 <= ly && ry <= qy2) return seg[idx(x, y)];
    int mid = (ly + ry) >> 1;
    int res = INT_MAX;
    if (qy1 <= mid) res = min(res, query_y(x, y << 1, ly, mid, qy1, qy2));
    if (qy2 > mid) res = min(res, query_y(x, y << 1 | 1, mid + 1, ry, qy1, qy2));
    return res;
}

int query_x(size_t x, int lx, int rx, int ql, int qr, int qy1, int qy2) {
    if (ql <= lx && rx <= qr) return query_y(x, 1, 0, C - 1, qy1, qy2);
    int mid = (lx + rx) >> 1;
    int res = INT_MAX;
    if (ql <= mid) res = min(res, query_x(x << 1, lx, mid, ql, qr, qy1, qy2));
    if (qr > mid) res = min(res, query_x(x << 1 | 1, mid + 1, rx, ql, qr, qy1, qy2));
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int r, c, q;
        if (!(cin >> r >> c >> q)) return 0; // EOF
        R = r; C = c; Q = q;
        grid.assign(R * C, 0);
        for (int i = 0; i < R; ++i) {
            for (int j = 0; j < C; ++j) {
                long long v; cin >> v; grid[i * C + j] = (int)v;
            }
        }
        // Initialize 2D segtree storage
        NY = 4ull * (size_t)C; // per x-node y-tree size
        NX = 4ull * (size_t)R; // number of x-nodes roughly
        seg.assign(NX * NY, INT_MAX);
        if (R > 0 && C > 0) build_x(1, 0, R - 1);
        for (int i = 0; i < Q; ++i) {
            int r1, c1, r2, c2; cin >> r1 >> c1 >> r2 >> c2;
            int ans = query_x(1, 0, R - 1, r1, r2, c1, c2);
            cout << ans << '\n';
        }
    }
    return 0;
}
