#include <bits/stdc++.h>
using namespace std;

// Decide if there exists a vertex cover of size <= k for given graph edges on 1..N
bool can(vector<pair<int,int>> edges, int N, int k) {
    if (edges.empty()) return true;
    if (k < 0) return false;

    // Reduction: if a vertex has degree > k, it must be in the cover
    while (true) {
        vector<int> deg(N+1, 0);
        for (auto &e : edges) {
            deg[e.first]++;
            deg[e.second]++;
        }
        int v = -1;
        for (int i = 1; i <= N; ++i) {
            if (deg[i] > k) { v = i; break; }
        }
        if (v == -1) break; // no more forced vertices
        // include v: remove all edges incident to v
        vector<pair<int,int>> newEdges;
        newEdges.reserve(edges.size());
        for (auto &e : edges) {
            if (e.first != v && e.second != v) newEdges.push_back(e);
        }
        edges.swap(newEdges);
        k--;
        if (k < 0) return false;
        if (edges.empty()) return true;
    }

    if (edges.empty()) return true;
    if (k == 0) return false;

    // Choose an edge and branch
    auto e = edges.back();
    int u = e.first, w = e.second;
    // Branch 1: include u
    {
        vector<pair<int,int>> e1;
        e1.reserve(edges.size());
        for (auto &ed : edges) if (ed.first != u && ed.second != u) e1.push_back(ed);
        if (can(e1, N, k-1)) return true;
    }
    // Branch 2: include w
    {
        vector<pair<int,int>> e2;
        e2.reserve(edges.size());
        for (auto &ed : edges) if (ed.first != w && ed.second != w) e2.push_back(ed);
        if (can(e2, N, k-1)) return true;
    }

    return false;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    if(!(cin >> N >> M >> K)) return 0;
    vector<pair<int,int>> edges;
    edges.reserve(M);
    for (int i = 0; i < M; ++i) {
        int a,b; cin >> a >> b; edges.emplace_back(a,b);
    }

    int ans = -1;
    for (int k = 0; k <= K; ++k) {
        if (can(edges, N, k)) { ans = k; break; }
    }

    if (ans == -1) cout << "Impossible\n";
    else cout << ans << "\n";
    return 0;
}
